6 | async function use(p:Page,x:number){await walk(p,x);await expect.poll(async()=>!!(await read(p)).player?.grounded).toBe(true);await p.keyboard.press('e');await p.waitForTimeout(100);}
7 | async function seed(p:Page,stage='S06',treasure=false){const s=freshSave();s.clearedStageIds=['S01','S02','S03','S04','S05'];if(stage==='S07')s.clearedStageIds.push('S06');s.checkpoint={stageId:stage,checkpointId:'start'};s.weapons.push('W02');s.flags=['bubbleBlessing'];s.totalXp=260;if(treasure){s.treasures=['T01'];s.weapons.push('W03');s.equippedSkill='flamePulse';}await p.addInitScript(({key,value})=>{if(!localStorage.getItem(key))localStorage.setItem(key,value);},{key:SAVE_KEY,value:JSON.stringify(s)});await p.goto('/');await p.getByRole('button',{name:`이어하기 · ${stage}`}).click();await expect.poll(async()=>(await read(p)).stage).toBe(stage);}
  |                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         ^
8 | async function defeat(p:Page,id:string){for(let i=0;i<12;i++){const e=(await read(p)).enemies.find((e:{id:string})=>e.id===id);if(!e||e.hp===0)return;await walk(p,e.x-65);await p.keyboard.down('d');await p.waitForTimeout(25);await p.keyboard.up('d');await p.keyboard.press('j');await p.waitForTimeout(450);}throw Error('Could not calm '+id);}

