3 | import {SAVE_KEY} from '../../src/core/save';
4 | const read=(p:Page)=>p.evaluate(()=>Reflect.get(window,'__SINBAD_TEST__'));
  |                        ^
5 | async function walk(p:Page,x:number){const end=Date.now()+30000;let jump=0;for(;;){const s=await read(p);if(!s.player){await p.waitForTimeout(50);continue;}if(Math.abs(s.player.x-x)<12)break;if(Date.now()>end)throw Error(`walk ${x}: ${JSON.stringify(s.player)}`);const key=s.player.x<x?'d':'a';await p.keyboard.up(key==='d'?'a':'d');await p.keyboard.down(key);if(Date.now()-jump>430){await p.keyboard.press('ArrowUp');jump=Date.now();}await p.waitForTimeout(60);}await p.keyboard.up('a');await p.keyboard.up('d');await p.waitForTimeout(450);}

